import{_ as a,o as r,c as e,a0 as d}from"./chunks/framework.akKRIpjQ.js";const g=JSON.parse('{"title":"00 · 项目介绍","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/00-introduction.md","filePath":"zh/guide/00-introduction.md"}'),o={name:"zh/guide/00-introduction.md"};function i(l,t,n,h,s,u){return r(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="_00-·-项目介绍" tabindex="-1">00 · 项目介绍 <a class="header-anchor" href="#_00-·-项目介绍" aria-label="Permalink to &quot;00 · 项目介绍&quot;">​</a></h1><blockquote><p><strong>AceCrush Craft</strong> — 网球爱好者的装备数据工具，离线优先、专注测算与记录。</p></blockquote><h2 id="它解决什么问题" tabindex="-1">它解决什么问题? <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题?&quot;">​</a></h2><p>打球几年之后，球包里有好几支拍、几条不同磅数的线、记不清&quot;上次换线是去年几月份&quot;。拍子参数、磅数换算、AI 测握把，全是工具活，但没人愿意为此打开十几个网页或者扔进 Excel。</p><p>AceCrush Craft 把日常会用到的 <strong>四件事</strong> 集中到一个 App 里：</p><table tabindex="0"><thead><tr><th>#</th><th>功能</th><th>你得到什么</th></tr></thead><tbody><tr><td>1</td><td><strong>握把尺寸测量</strong></td><td>拍照 AI（端侧 MediaPipe）→ 推荐尺码，或尺子手动输入（同一套公式）</td></tr><tr><td>2</td><td><strong>球拍档案</strong></td><td>多球拍、规格、备注，全在手机本地</td></tr><tr><td>3</td><td><strong>穿线记录</strong></td><td>每次换线写一行 + 到期提醒</td></tr><tr><td>4</td><td><strong>张力换算</strong></td><td>DT / RT / lbs / kg 互转 → 一键把算出的磅数带进穿线记录</td></tr></tbody></table><p>数据全部存在设备本地 SQLite，<strong>不上传</strong>。</p><h2 id="支持平台" tabindex="-1">支持平台 <a class="header-anchor" href="#支持平台" aria-label="Permalink to &quot;支持平台&quot;">​</a></h2><table tabindex="0"><thead><tr><th>平台</th><th>状态</th></tr></thead><tbody><tr><td><strong>Android</strong></td><td>✅ V1.0.x 已发布</td></tr><tr><td>iOS</td><td>❌ <strong>当前版本不支持</strong>（计划中，无可用构建）</td></tr><tr><td>Web / 桌面</td><td>❌ 不提供</td></tr></tbody></table><h2 id="版本路线" tabindex="-1">版本路线 <a class="header-anchor" href="#版本路线" aria-label="Permalink to &quot;版本路线&quot;">​</a></h2><table tabindex="0"><thead><tr><th>版本</th><th>状态</th><th>主轴</th></tr></thead><tbody><tr><td><strong>V1.0</strong></td><td>✅ 当前</td><td>上述 4 个功能</td></tr></tbody></table><h2 id="三大基石" tabindex="-1">三大基石 <a class="header-anchor" href="#三大基石" aria-label="Permalink to &quot;三大基石&quot;">​</a></h2><h3 id="_1-离线优先" tabindex="-1">1. 离线优先 <a class="header-anchor" href="#_1-离线优先" aria-label="Permalink to &quot;1. 离线优先&quot;">​</a></h3><p>除以下这类外，<strong>App 全部功能在无网环境下工作</strong>：</p><ul><li><strong>反馈提交</strong>（只有你按下&quot;发送&quot;才会发出）</li></ul><p>球拍档案、穿线日志、握把测算结果、提醒时间——<strong>全部存在设备本地 SQLite</strong>，卸载即清空，不上传任何服务器。</p><h3 id="_2-不打扰" tabindex="-1">2. 不打扰 <a class="header-anchor" href="#_2-不打扰" aria-label="Permalink to &quot;2. 不打扰&quot;">​</a></h3><ul><li><strong>没有推送矩阵</strong>：提醒通知只有&quot;换线到点&quot;这一类</li><li><strong>没有用户账号系统</strong>：V1.0 完全免登录</li></ul><h3 id="_3-可被独立验证" tabindex="-1">3. 可被独立验证 <a class="header-anchor" href="#_3-可被独立验证" aria-label="Permalink to &quot;3. 可被独立验证&quot;">​</a></h3><ul><li>每个计算器的输入与公式写在对应章节里，你可以拿计算器反算验证</li><li>AI 测握把的误差预估算在 <a href="./02-grip-size-measurement.html#误差预算与缓解">02 · 握把尺寸测量</a></li><li>所有网络行为都在 <a href="./08-privacy.html">08 · 隐私</a> 单独列出</li></ul><h2 id="四个功能速览" tabindex="-1">四个功能速览 <a class="header-anchor" href="#四个功能速览" aria-label="Permalink to &quot;四个功能速览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>章节</th><th>你能看到</th></tr></thead><tbody><tr><td><a href="./02-grip-size-measurement.html">02 · 握把尺寸测量</a></td><td>拍照 → MediaPipe Hand → 推荐尺码（也可尺子手动）</td></tr><tr><td><a href="./03-racquets.html">03 · 球拍档案</a></td><td>添加 / 编辑 / 删除球拍及规格</td></tr><tr><td><a href="./04-stringing-log.html">04 · 穿线记录</a></td><td>每次穿线写一条 + 自动提醒</td></tr><tr><td><a href="./05-tension-conversion.html">05 · 张力换算</a></td><td>DT ⇄ RT 换算；<strong>右下角「用此张力记录穿线」直接跳到第 4 章</strong></td></tr></tbody></table><h2 id="当前不做的事" tabindex="-1">当前<strong>不</strong>做的事 <a class="header-anchor" href="#当前不做的事" aria-label="Permalink to &quot;当前**不**做的事&quot;">​</a></h2><p>为了保持专注，下面这些<strong>V1.0 不会做</strong>：</p><ul><li>❌ 视频直播 / 比赛录像 / 社区</li><li>❌ 课程预约 / 教练对接 / 训练营</li><li>❌ 装备商城 / 电商</li><li>❌ 跨设备同步（V1.0 后期已上线，BYO Supabase；详见 <a href="./06-cloud-sync.html">06 · 云同步</a>）</li><li>❌ 智能手表 / 手环适配</li><li>❌ 球友 / 关注 / 评论</li></ul><h2 id="阅读路径" tabindex="-1">阅读路径 <a class="header-anchor" href="#阅读路径" aria-label="Permalink to &quot;阅读路径&quot;">​</a></h2><ul><li>第一次接触：<a href="./01-getting-started.html">01 · 快速开始</a> → 「加一支主力拍 → 录一次穿线」</li><li>好奇 AI 流程：<a href="./02-grip-size-measurement.html">02 · 握把尺寸测量</a></li><li>想试试「张力换算 → 穿线记录」一键跳：<a href="./05-tension-conversion.html">05 · 张力换算</a>（页面底部）</li></ul>',27)])])}const b=a(o,[["render",i]]);export{g as __pageData,b as default};
